    accountId: 'acct_1',
    sessionId: 'session_1',
    toolMode: 'read_only',
    identitySource: 'session',
    proxyToolName: 'composio-toolkit-googlesheets__googlesheets_values_update',
    serverName: 'composio-toolkit-googlesheets',
    downstreamToolName: 'googlesheets_values_update',
